import{_ as i,o as e,c as l,ag as t}from"./chunks/framework.ougANTrz.js";const d=JSON.parse('{"title":"智能体(Agentic)工程实践","description":"","frontmatter":{},"headers":[],"relativePath":"blogs/2026/202602-pov-agentic-engineering.md","filePath":"blogs/2026/202602-pov-agentic-engineering.md"}'),n={name:"blogs/2026/202602-pov-agentic-engineering.md"};function s(o,a,r,h,p,c){return e(),l("div",null,[...a[0]||(a[0]=[t(`<h1 id="智能体-agentic-工程实践" tabindex="-1">智能体(Agentic)工程实践 <a class="header-anchor" href="#智能体-agentic-工程实践" aria-label="Permalink to &quot;智能体(Agentic)工程实践&quot;">​</a></h1><p>参考软件工程的最佳实践，我们可以从三个维度思考 Agent 应用的开发流程：</p><ul><li>模块化：标准化职责、单一原则、提升复用性</li><li>结果驱动：可测试、可验证、可回归</li><li>持续演进：迭代优化、反馈闭环、版本管理</li></ul><h2 id="模块化" tabindex="-1">模块化 <a class="header-anchor" href="#模块化" aria-label="Permalink to &quot;模块化&quot;">​</a></h2><blockquote><p>Prompt ≈ Code Model ≈ Compiler Agent ≈ Application</p></blockquote><p>粗浅地看，我们可以将 Prompt 视为一种新的高级编程语言。它具有更高的抽象能力和表达力，但同时也带来了新的挑战：</p><ul><li>不确定性：大模型的输出具有随机性和多样性，难以保证结果的一致性和可预测性</li><li>黑盒性：大模型的内部机制和决策过程不透明，难以理解和调试</li><li>依赖性：大模型的性能和行为受训练数据和模型架构的影响，难以控制和优化</li><li>安全性：大模型可能产生有害、偏见或不适当的内容，难以防范和监管</li></ul><p>同样地，我们可以将 Agent 视为一种新的应用架构，它具有更高的智能能力和自主性。</p><h3 id="agent-的核心组件" tabindex="-1">Agent 的核心组件 <a class="header-anchor" href="#agent-的核心组件" aria-label="Permalink to &quot;Agent 的核心组件&quot;">​</a></h3><h4 id="system-instruction-系统指令" tabindex="-1">System Instruction（系统指令） <a class="header-anchor" href="#system-instruction-系统指令" aria-label="Permalink to &quot;System Instruction（系统指令）&quot;">​</a></h4><p>定义全局规则、角色与安全边界，默认生效。</p><ul><li>类似于：Environment Variables 或 Global Configuration</li><li>示例：SOUL.md、AGENT.md、CLAUDE.md</li></ul><h4 id="command-命令" tabindex="-1">Command（命令） <a class="header-anchor" href="#command-命令" aria-label="Permalink to &quot;Command（命令）&quot;">​</a></h4><p>用户主动触发的可执行命令。</p><ul><li>类似于：API Endpoint 或 CLI Command</li><li>示例：帮我写一封邮件、/search AI safety papers</li></ul><h4 id="skill-技能" tabindex="-1">Skill（技能） <a class="header-anchor" href="#skill-技能" aria-label="Permalink to &quot;Skill（技能）&quot;">​</a></h4><p>已掌握的可自主调用的能力。</p><ul><li>类似于：Dynamic Dispatch 进行条件匹配</li><li>示例：pdf-convert、code-execution、web-search</li></ul><h3 id="上下文与数据层" tabindex="-1">上下文与数据层 <a class="header-anchor" href="#上下文与数据层" aria-label="Permalink to &quot;上下文与数据层&quot;">​</a></h3><h4 id="memory-记忆" tabindex="-1">Memory（记忆） <a class="header-anchor" href="#memory-记忆" aria-label="Permalink to &quot;Memory（记忆）&quot;">​</a></h4><p>跨会话状态与偏好，确保连续性。</p><ul><li>类似于：Database 或 Cache</li><li>示例：User Profile Memory、Task State Memory</li></ul><h4 id="mcp-模型上下文协议" tabindex="-1">MCP（模型上下文协议） <a class="header-anchor" href="#mcp-模型上下文协议" aria-label="Permalink to &quot;MCP（模型上下文协议）&quot;">​</a></h4><p>外部能力接入层，为 Skill 和 Memory 提供数据与接口。</p><ul><li>类似于：3rd-party API</li><li>示例：Github MCP、Google Search MCP</li></ul><h3 id="agent-的封装与编排" tabindex="-1">Agent 的封装与编排 <a class="header-anchor" href="#agent-的封装与编排" aria-label="Permalink to &quot;Agent 的封装与编排&quot;">​</a></h3><p>将上述各层组合成可交付的最小智能体单元，就可以像使用传统软件一样进行版本管理、权限控制、测试和迭代。</p><h4 id="单个-agent" tabindex="-1">单个 Agent <a class="header-anchor" href="#单个-agent" aria-label="Permalink to &quot;单个 Agent&quot;">​</a></h4><p>将各层组合成可交付的最小智能体单元。</p><ul><li>类似于：Software Package 或 Service</li><li>示例：Email Assistant Agent、Research Assistant Agent</li></ul><h4 id="multi-agent-多智能体" tabindex="-1">Multi-Agent（多智能体） <a class="header-anchor" href="#multi-agent-多智能体" aria-label="Permalink to &quot;Multi-Agent（多智能体）&quot;">​</a></h4><p>多个 Agent 通过调度编排或自治协作完成复杂任务。</p><ul><li>类似于：Microservices Architecture</li><li>示例：Customer Support System with Email Agent, Chat Agent, and Knowledge Base Agent</li></ul><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  subgraph CA[Agent]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    SI[System Instruction]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    MS[Command]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    AS[Skill]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    MCP[MCP]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    M[Memory]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  end</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  U(&#39;User&#39;) --&gt; CA</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  SI --&gt; MS</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  SI --&gt; AS</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  MCP --&gt; MS</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  MCP --&gt; AS</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  M[Memory] --&gt; MCP</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  CA --&gt; Prompt</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Prompt --&gt; LLM</span></span></code></pre></div><hr><blockquote><p>参考：<a href="https://github.com/nibzard/awesome-agentic-patterns" target="_blank" rel="noreferrer">Awesome Agentic Patterns</a></p></blockquote><h2 id="结果驱动" tabindex="-1">结果驱动 <a class="header-anchor" href="#结果驱动" aria-label="Permalink to &quot;结果驱动&quot;">​</a></h2><h3 id="为什么需要结果驱动" tabindex="-1">为什么需要结果驱动 <a class="header-anchor" href="#为什么需要结果驱动" aria-label="Permalink to &quot;为什么需要结果驱动&quot;">​</a></h3><p>大模型具备先天的不确定性与黑盒属性，试错与迭代是必要流程。因此，每个模块都必须满足以下要求：</p><ul><li>可测试：能够验证功能是否正常</li><li>可复现：结果具有一定的一致性</li><li>可校验：能够评估输出质量</li><li>可回归：支持版本回滚和问题追踪</li></ul><p>设计与开发应先定义验收标准和验证路径，再实现能力编排。不可测试 = 不可上生产。</p><h3 id="从-代码-到-结果-的转变" tabindex="-1">从&quot;代码&quot;到&quot;结果&quot;的转变 <a class="header-anchor" href="#从-代码-到-结果-的转变" aria-label="Permalink to &quot;从&quot;代码&quot;到&quot;结果&quot;的转变&quot;">​</a></h3><p>如果将 Prompt 看作一种编程语言，那通过 Agent 生成的产物就相当于软件工程中的&quot;编译结果&quot;（如 .class 文件）。大多数情况下，我们并不需要关注它，而应该关注结果 —— 即用户的目标是否达成、价值是否创造。过度关注代码细节，反而会陷入微管理，降低效率和创新。</p><blockquote><p>&quot;坚持不去看除了 CLAUDE.md 以外的代码。杜绝对 AI 的 micromanagement（微管理）。用 AI 是锻炼一个领导者的 servant leadership 的很好的办法。&quot; —— <a href="https://mp.weixin.qq.com/s/9qPD3gXj3HLmrKC64Q6fbQ" target="_blank" rel="noreferrer">胡渊鸣 | 我给 10 个 Claude Code 打工</a></p></blockquote><h3 id="守护架构-放权代码" tabindex="-1">&quot;守护架构，放权代码&quot; <a class="header-anchor" href="#守护架构-放权代码" aria-label="Permalink to &quot;&quot;守护架构，放权代码&quot;&quot;">​</a></h3><p>这是更高杠杆的工作方式：</p><ul><li>聚焦结果与价值，而不是逐行控制代码细节</li><li>用边界与验收标准约束系统，而不是用微管理约束执行</li><li>把精力放在架构、优先级与反馈闭环这些高 leverage 决策上</li></ul><h2 id="持续演进" tabindex="-1">持续演进 <a class="header-anchor" href="#持续演进" aria-label="Permalink to &quot;持续演进&quot;">​</a></h2><h3 id="演进的必要性" tabindex="-1">演进的必要性 <a class="header-anchor" href="#演进的必要性" aria-label="Permalink to &quot;演进的必要性&quot;">​</a></h3><p>Agent 应该是一个持续演进的系统，而不是一次性交付的产品。通过以下方式不断提升 Agent 的能力和适应性：</p><ul><li>迭代优化：基于使用反馈持续改进</li><li>反馈闭环：建立用户反馈的收集与应用机制</li><li>版本管理：支持灰度发布、A/B 测试和快速回滚</li></ul><h3 id="设计原则" tabindex="-1">设计原则 <a class="header-anchor" href="#设计原则" aria-label="Permalink to &quot;设计原则&quot;">​</a></h3><p>从一开始就要考虑系统的长期可维护性：</p><ul><li>可维护性：清晰的模块划分和文档</li><li>可扩展性：预留扩展接口，支持新能力接入</li><li>可升级性：避免技术债务和过度耦合</li></ul><h2 id="个人实践" tabindex="-1">个人实践 <a class="header-anchor" href="#个人实践" aria-label="Permalink to &quot;个人实践&quot;">​</a></h2><h3 id="github-copilot" tabindex="-1">Github Copilot <a class="header-anchor" href="#github-copilot" aria-label="Permalink to &quot;Github Copilot&quot;">​</a></h3><p><a href="https://code.visualstudio.com/docs/copilot/customization/overview" target="_blank" rel="noreferrer">Customize AI in Visual Studio Code</a>，Copilot 已经支持绝大多数的 Agentic 技术，包括：</p><ul><li><code>.github/copilot-instructions.md</code> = System Instruction</li><li><code>.github/prompts/*.prompt.md</code> = Command</li><li><code>.github/skills/*/SKILL.md</code> = Skill</li><li>MCP &amp; Custom Agent</li></ul><p>在不更改开发环境的情况下，通过自定义的指令逐步构建智能体工作流，最后替代大部分的重复性工作。如：/test-golang, /code-review, /debug-kubernetes, /get-my-jira-tickets ...</p><h3 id="memory" tabindex="-1">Memory <a class="header-anchor" href="#memory" aria-label="Permalink to &quot;Memory&quot;">​</a></h3><p>Memory 主要用于存储用户的偏好、历史交互和上下文信息，以便在跨 Session 的交互中保持连续性。实现方式：</p><ul><li>文件系统：将 Memory 存储在指定路径的文件中，将路径作为输入</li><li>文件系统+skill：提供读写 Memory 的技能，无需提供具体路径，e.g. OpenSpec</li><li>MCP：将 Memory 存储在外部系统（数据库）中，通过 MCP 提供接口访问，e.g. OpenMemory</li></ul><hr><blockquote><p>🤖 AI投喂建议：</p><ul><li>“Command 和 Skill 的区别”</li><li>“Agent 的版本管理和回滚机制”</li><li>“如何测试和评估 Agent 的输出质量”</li></ul></blockquote>`,64)])])}const m=i(n,[["render",s]]);export{d as __pageData,m as default};
